fs.mkdirSync(SVGDIR,{recursive:true}); fs.mkdirSync(OUT,{recursive:true});
const namen=Object.keys(T);
namen.forEach(function(n){ fs.writeFileSync(path.join(SVGDIR,"tegel-"+n+".svg"), T[n]); });
execSync('qlmanage -t -s 256 -o "'+OUT+'" "'+SVGDIR+'"/*.svg', {stdio:"ignore"});
namen.forEach(function(n){ var s=path.join(OUT,"tegel-"+n+".svg.png"), d=path.join(OUT,"tegel-"+n+".png"); if(fs.existsSync(s)) fs.renameSync(s,d); });
// QuickLook rendert op wit; achtergrond transparant maken (wit BINNEN de tekening blijft)
execSync('python3 "'+path.join(ROOT,"tools","witweg.py")+'" "'+OUT+'"/*.png', {stdio:"ignore"});
const ok=namen.filter(function(n){ return fs.existsSync(path.join(OUT,"tegel-"+n+".png")); });
console.error("gerenderd:", ok.length, "/", namen.length);
if(process.argv.indexOf("--install")>=0){
  ok.forEach(function(n){ var b=path.join(OUT,"tegel-"+n+".png");
    fs.copyFileSync(b, path.join(DST,"tegel-"+n+".png"));
    ["t1","t2","t3"].forEach(function(t){ fs.copyFileSync(b, path.join(DST,"tegel-"+n+"-"+t+".png")); }); });
  console.error("geïnstalleerd in tegels/:", ok.length);
}
